-- Carpeta "Proceso de ventas": 6 manuales de procedimiento (borrador 0.1, sin publicar).
-- La pantalla de Manuales agrupa por la columna area, así que todos van con area = 'Proceso de ventas'.
-- Correr en el phpMyAdmin de EasyPanel. La tabla manuales se crea sola la primera vez que
-- alguien abre la sección Manuales del panel: si el INSERT dice que no existe, abrir la sección y repetir.

-- Antes: no debe devolver filas (si devuelve, ya están cargados: no correr los INSERT).
SELECT id, codigo, titulo, version FROM supricom_panel.manuales WHERE codigo IN ('MP-VEN-00', 'MP-VEN-01', 'MP-VEN-02', 'MP-VEN-03', 'MP-VEN-04', 'MP-VEN-05');

INSERT INTO supricom_panel.manuales (codigo, titulo, area, version, roles, publicado, contenido, updated_by)
VALUES ('MP-VEN-00', 'Proceso de ventas: visión general', 'Proceso de ventas', '0.1', '[]', 0, '{"objetivo":"Mostrar el proceso de venta completo de SUPRICOM, de la primera cotización hasta que la mercancía sale por el portón, y qué le toca a cada área.\\n\\nCada área tiene su propio manual en esta carpeta:\\n- MP-VEN-01 Ventas (vendedores, asistentes y Gerente de Ventas).\\n- MP-VEN-02 Cuentas por Cobrar: plazos y crédito.\\n- MP-VEN-03 Facturación.\\n- MP-VEN-04 Almacén: armado y despacho.\\n- MP-VEN-05 Seguridad: verificación en el portón.\\n\\nEste manual es el mapa: dice quién entrega qué a quién y las reglas que todos cumplen. El detalle de cada paso está en el manual de cada área.","alcance":"Empieza cuando el vendedor prepara la primera cotización para un cliente y termina cuando Seguridad aprueba la salida en el portón y califica el despacho.\\n\\nAplica a las sedes Valencia y Caracas. Panamá lo adopta después del piloto, con sus propios montos de ruta gratis.\\n\\nNo cubre (tienen o tendrán su propio manual): devoluciones, garantías y notas de crédito (RMA); la cobranza después de facturar; compras y recepción de mercancía.\\n\\nREGLAS DEL PROCESO (aplican a todas las áreas)\\n- R1. Toda venta pasa por una cotización en Odoo. No se carga el pedido después de despachar.\\n- R2. Toda cotización se cierra: se confirma o se cancela con el motivo anotado. Ninguna queda en borrador más de 15 días.\\n- R3. No se vende por debajo del costo ni se aplica un descuento fuera de la tabla sin aprobación anotada en Odoo.\\n- R4. El descuento se pone en la columna \\"Desc. %\\" de la línea, nunca bajando el precio unitario a mano.\\n- R5. El vendedor no cambia el plazo de pago. El plazo lo asigna Cuentas por Cobrar en la ficha del cliente.\\n- R6. A un cliente con facturas vencidas hace más de 30 días o por encima de su límite de crédito solo se le vende de contado, salvo aprobación de Cuentas por Cobrar anotada en el pedido.\\n- R7. Un pedido, una factura: la factura se crea desde el mismo pedido que se despacha. No se duplican pedidos.\\n- R8. Un pedido confirmado no se cancela si la mercancía ya salió: se tramita una devolución.\\n- R9. Ninguna mercancía sale del almacén sin factura publicada, método de retiro y verificación de Seguridad. La orden de entrega se valida solo por el panel, nunca a mano en Odoo.\\n\\nLos números de R2, R3 y R6 son una propuesta (versión 0.1) y los confirma la Gerencia antes de publicar.","responsables":[{"rol":"Gerente de Ventas","responsabilidad":"Dueño del proceso completo. Aprueba descuentos y precios fuera de la tabla y revisa los indicadores cada semana."},{"rol":"Vendedor / Asistente de Ventas","responsabilidad":"Cotiza, confirma el pedido y registra el método de retiro (MP-VEN-01)."},{"rol":"Cuentas por Cobrar","responsabilidad":"Asigna plazos y límites de crédito y aprueba las excepciones de crédito (MP-VEN-02)."},{"rol":"Facturación (Caja / Administración)","responsabilidad":"Revisa y factura el pedido (MP-VEN-03)."},{"rol":"Almacén","responsabilidad":"Registra el egreso, arma, cuenta y despacha por el panel (MP-VEN-04)."},{"rol":"Seguridad","responsabilidad":"Verifica la salida en el portón y califica el despacho (MP-VEN-05)."},{"rol":"Procesos","responsabilidad":"Mantiene esta carpeta de manuales, mide su cumplimiento y la actualiza."}],"definiciones":[{"termino":"Cotización","definicion":"Documento de Odoo (Ventas) con los productos, precios y condiciones que se ofrecen al cliente. Mientras no se confirma está en estado Cotización (borrador) o Cotización enviada."},{"termino":"Pedido de venta","definicion":"Cotización confirmada (estado Orden de venta). Al confirmarla, Odoo reserva el inventario y crea la orden de entrega."},{"termino":"Factura publicada","definicion":"Factura de cliente en estado Publicado (no borrador ni revertida) creada desde el pedido. Sin ella el panel no deja registrar el egreso."},{"termino":"Orden de entrega","definicion":"Documento de inventario de Odoo (CENT1/OUT/…, PRIN1/OUT/…) que nace del pedido. Tiene que estar en estado Listo (reservado) para que Almacén lo vea en el panel."},{"termino":"Método de retiro","definicion":"Cómo recibe el cliente la mercancía: sucursal, ruta, encomienda o transporte. Se registra en el panel (Método de retiro) por cada pedido."},{"termino":"Egreso","definicion":"Registro del panel que sigue la salida de un pedido por etapas: por armar → armando → pre-despacho → (por empaquetar) → por asignar despacho → por verificar → por calificar → cerrado."},{"termino":"Desviación","definicion":"Paso de un manual que no se cumplió. Se anota con su motivo y quién la autorizó."}],"pasos":[{"titulo":"Verificar al cliente y su condición de pago","responsable":"Vendedor (con Cuentas por Cobrar)","descripcion":"El vendedor revisa la ficha y el estado de cuenta del cliente en Odoo. Si el cliente es nuevo y pide crédito, o tiene deuda vencida, consulta a Cuentas por Cobrar.\\nEntrega: cliente con ficha completa y condición de pago definida.\\nDetalle: MP-VEN-01 paso 1 y MP-VEN-02.","imagenes":[],"nota":""},{"titulo":"Cotizar, enviar y dar seguimiento","responsable":"Vendedor","descripcion":"Cotización en Odoo con precios de la lista, descuentos dentro de la tabla, enviada desde Odoo y cerrada (ganada o cancelada) en máximo 15 días.\\nEntrega: cotización aceptada por el cliente por escrito.\\nDetalle: MP-VEN-01 pasos 2 a 4.","imagenes":[],"nota":""},{"titulo":"Confirmar el pedido y registrar el método de retiro","responsable":"Vendedor / Asistente de Ventas","descripcion":"El vendedor confirma el pedido con la lista de chequeo y registra el método de retiro en el panel el mismo día.\\nEntrega a Facturación: pedido confirmado, completo y con sus aprobaciones anotadas.\\nDetalle: MP-VEN-01 pasos 5 y 6.","imagenes":[],"nota":""},{"titulo":"Facturar","responsable":"Facturación","descripcion":"Facturación revisa el pedido y publica la factura desde ese mismo pedido.\\nEntrega a Almacén: factura publicada (el pedido aparece solo en la lista de pendientes del panel).\\nDetalle: MP-VEN-03.","imagenes":[],"nota":""},{"titulo":"Armar y despachar","responsable":"Almacén","descripcion":"Almacén registra el egreso, arma, cuenta, carga seriales y asigna el despacho en el panel, que valida la orden de entrega en Odoo.\\nEntrega a Seguridad: egreso en Por verificar.\\nDetalle: MP-VEN-04.","imagenes":[],"nota":""},{"titulo":"Verificar en el portón y cerrar","responsable":"Seguridad","descripcion":"Seguridad escanea, firma el acta, decide qué hacer con las novedades y califica el despacho.\\nFin del proceso: egreso Cerrado. El vendedor avisa al cliente que su pedido salió (MP-VEN-01 paso 7).\\nDetalle: MP-VEN-05.","imagenes":[],"nota":""}],"documentos":"EXCEPCIONES\\n- Toda excepción a una regla (descuento, precio bajo costo, plazo, crédito con deuda vencida, despacho parcial) se aprueba ANTES de hacerla y se anota en el chatter del pedido en Odoo: quién aprobó, qué y por qué.\\n- Un paso que no se cumplió es una desviación. Si se repite, Procesos revisa con el área si el problema es la persona o el manual, y corrige lo que haga falta.\\n- Los errores caros (despacho equivocado, venta con pérdida, mercancía que salió sin factura) se revisan en una reunión corta sin buscar culpables: qué pasó, por qué y qué se cambia para que no se repita.\\n\\nINDICADORES DEL PROCESO (detalle y meta en el manual de cada área)\\n- Ventas: cotizaciones abiertas con más de 15 días, pedidos con referencia del cliente, líneas bajo costo sin aprobación.\\n- Cuentas por Cobrar: ventas a crédito a clientes con deuda vencida sin aprobación.\\n- Facturación: pedidos despachados sin factura propia.\\n- Almacén: órdenes de entrega validadas fuera del panel.\\n- Seguridad: egresos aprobados con novedades.\\n\\nREVISIÓN\\n- Dueño: Gerente de Ventas. Mantiene: Procesos.\\n- Se revisa cada 3 meses, y antes si cambia el proceso, Odoo o el panel.","cambios":[{"version":"0.1","fecha":"2026-10-08","descripcion":"Borrador inicial. Pendiente: la Gerencia confirma los números de las reglas R2, R3 y R6."}]}', 'Procesos');

INSERT INTO supricom_panel.manuales (codigo, titulo, area, version, roles, publicado, contenido, updated_by)
VALUES ('MP-VEN-01', 'Ventas: de la cotización al pedido confirmado', 'Proceso de ventas', '0.1', '[]', 0, '{"objetivo":"Que el vendedor cotice, confirme y entregue a Facturación cada pedido completo, con precios, descuentos y condiciones de pago dentro de las reglas, y que quede registro de todo en Odoo.\\n\\nVender mucho no exime de este manual: las reglas son iguales para todos los vendedores.","alcance":"Empieza cuando el vendedor prepara la primera cotización y termina cuando el pedido está confirmado y con método de retiro. Incluye avisar al cliente cuando su pedido sale.\\n\\nAplica a vendedores, asistentes de ventas y Gerente de Ventas de Valencia y Caracas.\\n\\nReglas de este manual: R1 a R5 de MP-VEN-00 (cotización obligatoria, cierre en 15 días, nada bajo costo sin aprobación, descuento en \\"Desc. %\\", el vendedor no cambia el plazo de pago).","responsables":[{"rol":"Vendedor","responsabilidad":"Hace los pasos 1 a 7. Responde por que sus cotizaciones y pedidos estén completos y correctos."},{"rol":"Asistente de Ventas","responsabilidad":"Puede registrar el método de retiro de cualquier pedido de la sede y revisa cada mañana los pedidos confirmados que no lo tienen."},{"rol":"Gerente de Ventas","responsabilidad":"Aprueba descuentos de 5 % a 10 % y precios fuera de la tabla, autoriza correcciones de pedidos confirmados y revisa cada semana los indicadores con cada vendedor."}],"definiciones":[{"termino":"Cotización","definicion":"Documento de Odoo (Ventas) con los productos, precios y condiciones que se ofrecen al cliente. Mientras no se confirma está en estado Cotización (borrador) o Cotización enviada."},{"termino":"Cotización enviada","definicion":"Cotización que se mandó al cliente desde Odoo con \\"Enviar por correo electrónico\\". Queda constancia de qué se ofreció y cuándo."},{"termino":"Vencimiento (vigencia)","definicion":"Fecha hasta la que vale la cotización. Pasada esa fecha, los precios se revisan antes de confirmar."},{"termino":"Costo","definicion":"Costo del producto que muestra Odoo en la línea (margen). Vender por debajo de él es vender con pérdida."},{"termino":"Pedido de venta","definicion":"Cotización confirmada (estado Orden de venta). Al confirmarla, Odoo reserva el inventario y crea la orden de entrega."},{"termino":"Referencia del cliente","definicion":"Número de la orden de compra del cliente o, si no tiene, cómo aceptó (correo, WhatsApp, firma). Va en el pedido, pestaña Otra información."},{"termino":"Plazo de pago","definicion":"Condición de pago del pedido y la factura (Pago inmediato, 7, 15, 21, 30… días). Sale de la ficha del cliente y lo asigna Cuentas por Cobrar."},{"termino":"Límite de crédito","definicion":"Monto máximo que el cliente puede deber. Lo fija Cuentas por Cobrar en la ficha del cliente. Odoo avisa cuando se supera, pero no bloquea: por eso es una regla de estos manuales."},{"termino":"Método de retiro","definicion":"Cómo recibe el cliente la mercancía: sucursal, ruta, encomienda o transporte. Se registra en el panel (Método de retiro) por cada pedido."}],"pasos":[{"titulo":"Verificar al cliente en Odoo antes de cotizar","responsable":"Vendedor","descripcion":"Sistema: Odoo › Contactos y Contabilidad › Clientes.\\n- Busca al cliente por RIF. Si no existe, créalo con RIF, razón social, dirección, teléfono y correo. Nunca dupliques una ficha.\\n- Revisa en su ficha el plazo de pago y el límite de crédito.\\n- Revisa su estado de cuenta: facturas vencidas y cuánto debe.\\n\\nDecide con esta tabla:\\n- Al día y dentro de su límite: puedes ofrecer el plazo de su ficha.\\n- Con facturas vencidas hace más de 30 días o sobre su límite: solo contado, salvo aprobación de Cuentas por Cobrar (regla R6).\\n- Cliente nuevo sin plazo asignado: contado. Si pide crédito, pide a Cuentas por Cobrar que lo evalúe (MP-VEN-02).\\n\\nCriterio de salida: cliente con ficha completa y condición de pago definida.","imagenes":[],"nota":"El vendedor no cambia el plazo de pago de la ficha ni el del pedido. Si el cliente pide más días, lo decide Cuentas por Cobrar."},{"titulo":"Crear la cotización en Odoo","responsable":"Vendedor","descripcion":"Sistema: Odoo › Ventas › Órdenes › Cotizaciones › Nuevo.\\nLlena siempre:\\n- Cliente (la ficha verificada en el paso 1) y dirección de entrega.\\n- Vencimiento: 7 días desde hoy (propuesta, a confirmar por la Gerencia).\\n- Lista de precios de la sede.\\n- Términos de pago: los de la ficha del cliente. No los cambies.\\n- Productos y cantidades. Revisa el ícono de disponibilidad de cada línea: si no hay stock, díselo al cliente con fecha estimada o quita la línea.\\n\\nPrecios y descuentos:\\n- Usa el precio de la lista. Si das descuento, ponlo en la columna \\"Desc. %\\" (regla R4).\\n- Revisa el margen de cada línea. Si algún precio queda por debajo del costo, la cotización no se envía sin aprobación (regla R3).\\n- Tabla de descuentos (propuesta, a confirmar): hasta 5 % lo decide el vendedor; de 5 % a 10 % lo aprueba el Gerente de Ventas; más de 10 % o por debajo del costo lo aprueba la Gerencia General.\\n- La aprobación se pide antes de enviar la cotización y se anota en el chatter de Odoo (\\"Registrar nota\\": quién aprobó, cuánto y por qué).\\n\\nCriterio de salida: cotización completa, con precios dentro de la tabla o con la aprobación anotada.","imagenes":[],"nota":""},{"titulo":"Enviar la cotización al cliente","responsable":"Vendedor","descripcion":"Sistema: Odoo › botón \\"Enviar por correo electrónico\\".\\n- Envía la cotización desde Odoo para que quede en estado Cotización enviada y con copia en el chatter.\\n- Si el cliente la prefiere por WhatsApp, descarga el PDF desde Odoo, envíaselo y anota en el chatter que se mandó por WhatsApp y la fecha.\\n- No mandes precios por WhatsApp sin una cotización de Odoo detrás.\\n\\nCriterio de salida: cotización en estado Cotización enviada.","imagenes":[],"nota":""},{"titulo":"Dar seguimiento y cerrar la cotización","responsable":"Vendedor","descripcion":"Sistema: Odoo › Ventas › Cotizaciones (filtro Mis cotizaciones).\\n- Revisa tus cotizaciones abiertas cada lunes.\\n- Contacta al cliente antes de que venza cada cotización.\\n- Si el cliente acepta: sigue al paso 5.\\n- Si cambia algo: edita la misma cotización (no crees una nueva) y vuelve a enviarla.\\n- Si no compra o no responde en 15 días: cancela la cotización y anota el motivo en el chatter (precio, sin stock, compró a otro, sin respuesta…).\\n\\nCriterio de salida: ninguna cotización tuya en borrador con más de 15 días (regla R2).","imagenes":[],"nota":"Cancelar una cotización perdida no es malo: es información. Lo que no se acepta es dejarla abierta o crear otra igual."},{"titulo":"Confirmar el pedido","responsable":"Vendedor","descripcion":"Sistema: Odoo › botón \\"Confirmar\\".\\nConfirma solo cuando el cliente aceptó por escrito (orden de compra, correo o mensaje). Antes de pulsar Confirmar, revisa esta lista:\\n- [ ] El cliente y la dirección de entrega son los correctos.\\n- [ ] La Referencia del cliente (pestaña Otra información) tiene su número de orden de compra o cómo aceptó.\\n- [ ] Los términos de pago son los de la ficha, o la excepción está aprobada y anotada.\\n- [ ] Si el cliente tiene deuda vencida, está la aprobación de Cuentas por Cobrar o es de contado.\\n- [ ] Ningún precio está por debajo del costo sin aprobación anotada.\\n- [ ] Los descuentos están en \\"Desc. %\\" y dentro de la tabla, o aprobados.\\n- [ ] La cotización no está vencida, o revisaste los precios.\\n- [ ] Hay stock reservable, o el cliente sabe que la entrega es parcial.\\n- [ ] No existe otro pedido igual para el mismo cliente (regla R7).\\n\\nExcepción: en una venta de mostrador de contado con el cliente presente se puede crear y confirmar el pedido en el momento, cumpliendo igual la lista.\\n\\nCriterio de salida: pedido en estado Orden de venta, con la orden de entrega creada.","imagenes":[],"nota":"Un pedido confirmado no se modifica en precios ni plazos. Si hay que corregirlo antes de facturar, pide al Gerente de Ventas que lo autorice y anota el cambio en el chatter."},{"titulo":"Registrar el método de retiro","responsable":"Vendedor / Asistente de Ventas","descripcion":"Sistema: panel › Método de retiro.\\n- El mismo día en que confirmas el pedido, elige cómo lo recibe el cliente: sucursal, ruta (con la ruta), encomienda (con la agencia) o transporte (con la empresa).\\n- El panel calcula si la ruta es gratis según el monto y avisa si hay irregularidades. Si el cliente no llega al monto, acuerda el costo con él antes de registrar.\\n- El Asistente de Ventas revisa cada mañana los pedidos confirmados de la sede que siguen sin método.\\n\\nCriterio de salida: pedido con método de retiro. Sin él, Almacén no puede registrar el egreso.","imagenes":[],"nota":""},{"titulo":"Avisar al cliente y atender después de la salida","responsable":"Vendedor","descripcion":"- Cuando el pedido sale, avisa al cliente cómo y cuándo le llega.\\n- Si Almacén te avisa de un faltante o un despacho parcial, informa al cliente el mismo día.\\n- Si el cliente reporta un faltante o un producto dañado, no lo resuelvas por tu cuenta: abre el caso por el proceso de RMA o de devolución.\\n- Si el cliente quiere devolver o anular un pedido ya despachado, no se cancela el pedido en Odoo (regla R8): se tramita la devolución.","imagenes":[],"nota":""}],"documentos":"REGISTROS\\n- Cotización, aprobaciones de descuento o precio y motivo de cancelación: Odoo, pedido y su chatter.\\n- Aceptación del cliente: Odoo, campo Referencia del cliente (y el correo u orden de compra adjuntos al chatter).\\n- Método de retiro: panel.\\n\\nINDICADORES (el Gerente de Ventas los revisa cada semana con cada vendedor)\\n- Cotizaciones en borrador con más de 15 días. Meta: 0. Hoy: entre 0 y 117 por vendedor con más de 30 días (abr-oct 2026).\\n- Pedidos confirmados con Referencia del cliente. Meta: 100 %. Hoy: 0 %.\\n- Líneas vendidas por debajo del costo sin aprobación. Meta: 0. Hoy: 852 líneas en Valencia y 348 en Caracas (abr-oct 2026, cifra a verificar con el costo de Odoo).\\n- Pedidos confirmados sin método de retiro después de 24 horas. Meta: 0.\\n- Pedidos duplicados (dos pedidos iguales para el mismo cliente, uno sin facturar). Meta: 0.","cambios":[{"version":"0.1","fecha":"2026-10-08","descripcion":"Borrador inicial. Pendiente: la Gerencia confirma la vigencia de 7 días, la tabla de descuentos y los 15 días para cerrar una cotización."}]}', 'Procesos');

INSERT INTO supricom_panel.manuales (codigo, titulo, area, version, roles, publicado, contenido, updated_by)
VALUES ('MP-VEN-02', 'Cuentas por Cobrar: plazos y crédito en la venta', 'Proceso de ventas', '0.1', '[]', 0, '{"objetivo":"Que cada cliente tenga un plazo de pago y un límite de crédito definidos por Cuentas por Cobrar, y que no se venda a crédito a quien tiene deuda vencida sin una decisión registrada.","alcance":"Cubre lo que Cuentas por Cobrar hace ANTES de facturar: asignar plazos y límites, evaluar a los clientes que piden crédito y aprobar o rechazar excepciones.\\n\\nNo cubre la cobranza de facturas ya emitidas (tendrá su propio manual).\\n\\nReglas de este manual: R5 y R6 de MP-VEN-00 (el vendedor no cambia el plazo; con deuda vencida de más de 30 días o sobre el límite, solo contado salvo aprobación de Cuentas por Cobrar).","responsables":[{"rol":"Cuentas por Cobrar","responsabilidad":"Asigna plazos y límites en la ficha del cliente, evalúa solicitudes de crédito y aprueba o rechaza excepciones. Es el único que cambia el plazo o el límite de un cliente."},{"rol":"Vendedor","responsabilidad":"Pide la evaluación o la excepción con los datos del cliente y espera la respuesta antes de confirmar el pedido."},{"rol":"Gerente de Ventas","responsabilidad":"Opina sobre la importancia comercial del cliente cuando Cuentas por Cobrar lo consulta. No aprueba crédito solo."}],"definiciones":[{"termino":"Plazo de pago","definicion":"Condición de pago del pedido y la factura (Pago inmediato, 7, 15, 21, 30… días). Sale de la ficha del cliente y lo asigna Cuentas por Cobrar."},{"termino":"Límite de crédito","definicion":"Monto máximo que el cliente puede deber. Lo fija Cuentas por Cobrar en la ficha del cliente. Odoo avisa cuando se supera, pero no bloquea: por eso es una regla de estos manuales."},{"termino":"Factura vencida","definicion":"Factura publicada con saldo pendiente y fecha de vencimiento ya pasada."},{"termino":"Excepción de crédito","definicion":"Autorización puntual para vender a crédito a un cliente con deuda vencida o sobre su límite. Vale para un solo pedido."}],"pasos":[{"titulo":"Asignar plazo y límite en la ficha del cliente","responsable":"Cuentas por Cobrar","descripcion":"Sistema: Odoo › Contactos › ficha del cliente › pestaña Ventas y compras / Contabilidad.\\n- Todo cliente nuevo queda en \\"Pago inmediato\\" y sin límite hasta que se evalúe.\\n- Al aprobar crédito, pon el plazo de pago y el límite de crédito en la ficha.\\n- Anota en el chatter de la ficha quién aprobó, el plazo, el límite y la fecha.","imagenes":[],"nota":""},{"titulo":"Evaluar una solicitud de crédito","responsable":"Cuentas por Cobrar","descripcion":"- Recibe la solicitud del vendedor con RIF, datos del cliente y monto esperado de compra.\\n- Revisa su historial de pagos en Odoo (si ya compró de contado) y las referencias que pida la empresa.\\n- Responde al vendedor en máximo 2 días hábiles (propuesta): aprobado (con plazo y límite) o rechazado (con el motivo).","imagenes":[],"nota":""},{"titulo":"Aprobar o rechazar una excepción de crédito","responsable":"Cuentas por Cobrar","descripcion":"Cuándo: el vendedor quiere vender a crédito a un cliente con facturas vencidas hace más de 30 días o por encima de su límite.\\n- Revisa la deuda vencida y si hay un compromiso de pago.\\n- Si apruebas, anótalo en el chatter del pedido en Odoo: quién aprueba, monto, motivo y, si aplica, la fecha del compromiso de pago.\\n- Si rechazas, el pedido solo puede seguir de contado.","imagenes":[],"nota":"Sin la nota en el chatter, Facturación no factura el pedido a crédito."},{"titulo":"Revisar plazos y límites cada mes","responsable":"Cuentas por Cobrar","descripcion":"- Revisa los clientes que pagan tarde de forma repetida y ajusta su plazo o su límite.\\n- Revisa los pedidos a crédito del mes a clientes con deuda vencida y confirma que todos tenían su aprobación.","imagenes":[],"nota":""}],"documentos":"REGISTROS\\n- Plazo y límite: ficha del cliente en Odoo y su chatter.\\n- Excepciones: chatter del pedido en Odoo.\\n\\nINDICADORES\\n- Ventas a crédito a clientes con facturas vencidas hace más de 30 días sin aprobación anotada. Meta: 0. Hoy: al menos 151 pedidos en Valencia y 47 en Caracas (may-oct 2026).\\n- Clientes nuevos con crédito sin evaluación registrada. Meta: 0.","cambios":[{"version":"0.1","fecha":"2026-10-08","descripcion":"Borrador inicial. Pendiente: la Gerencia confirma el límite de 30 días de deuda vencida y el plazo de respuesta de 2 días hábiles; Cuentas por Cobrar define qué referencias pide para dar crédito."}]}', 'Procesos');

INSERT INTO supricom_panel.manuales (codigo, titulo, area, version, roles, publicado, contenido, updated_by)
VALUES ('MP-VEN-03', 'Facturación del pedido de venta', 'Proceso de ventas', '0.1', '[]', 0, '{"objetivo":"Que cada pedido confirmado se facture una sola vez, desde el mismo pedido, con las condiciones aprobadas, para que Almacén pueda despacharlo.","alcance":"Empieza cuando el vendedor confirma el pedido y termina con la factura publicada y enlazada al pedido.\\n\\nReglas de este manual: R6, R7 y R9 de MP-VEN-00.","responsables":[{"rol":"Facturación (Caja / Administración)","responsabilidad":"Revisa el pedido, emite y publica la factura. Devuelve al vendedor los pedidos incompletos o sin aprobación."},{"rol":"Vendedor","responsabilidad":"Corrige el pedido que Facturación le devuelve."}],"definiciones":[{"termino":"Pedido de venta","definicion":"Cotización confirmada (estado Orden de venta). Al confirmarla, Odoo reserva el inventario y crea la orden de entrega."},{"termino":"Factura publicada","definicion":"Factura de cliente en estado Publicado (no borrador ni revertida) creada desde el pedido. Sin ella el panel no deja registrar el egreso."},{"termino":"Plazo de pago","definicion":"Condición de pago del pedido y la factura (Pago inmediato, 7, 15, 21, 30… días). Sale de la ficha del cliente y lo asigna Cuentas por Cobrar."},{"termino":"Referencia del cliente","definicion":"Número de la orden de compra del cliente o, si no tiene, cómo aceptó (correo, WhatsApp, firma). Va en el pedido, pestaña Otra información."}],"pasos":[{"titulo":"Revisar el pedido antes de facturar","responsable":"Facturación","descripcion":"Sistema: Odoo › Ventas › Órdenes › A facturar.\\n- [ ] Tiene Referencia del cliente.\\n- [ ] El plazo de pago es el de la ficha, o hay excepción anotada por Cuentas por Cobrar.\\n- [ ] Si hay precios bajo costo o descuentos fuera de tabla, la aprobación está en el chatter.\\n- [ ] No hay otro pedido igual del mismo cliente ya facturado (regla R7).\\nSi falta algo, devuélvelo al vendedor con una nota en el chatter y no lo factures.","imagenes":[],"nota":""},{"titulo":"Crear y publicar la factura desde el pedido","responsable":"Facturación","descripcion":"Sistema: Odoo › pedido › Crear factura › Confirmar.\\n- Crea la factura siempre desde el pedido que se va a despachar, nunca desde otro pedido ni a mano.\\n- Pago inmediato (contado): factura cuando el pago está recibido o verificado (propuesta, a confirmar con Administración).\\n- Crédito: factura con el plazo del pedido.\\n- Publica la factura. Una factura en borrador no habilita la salida en el panel.\\n\\nCriterio de salida: factura publicada, con el pedido como origen.","imagenes":[],"nota":"Si el cliente pide facturar dos pedidos en una sola factura, selecciona ambos pedidos y créala desde ahí, para que quede enlazada a los dos."},{"titulo":"Corregir una factura","responsable":"Facturación","descripcion":"- No borres ni dejes en borrador una factura de un pedido que ya salió.\\n- Si hay un error, emite la nota de crédito y la factura nueva desde el mismo pedido, y anota el motivo en el chatter.","imagenes":[],"nota":""}],"documentos":"REGISTROS\\n- Factura y su origen (pedido): Odoo.\\n- Pedidos devueltos al vendedor: chatter del pedido.\\n\\nINDICADORES\\n- Pedidos despachados sin una factura publicada propia. Meta: 0. Hoy: hubo casos entre abril y septiembre de 2026; desde el 30-09-2026 el panel no deja sacar mercancía sin factura.\\n- Facturas creadas desde un pedido distinto al que se despachó. Meta: 0.","cambios":[{"version":"0.1","fecha":"2026-10-08","descripcion":"Borrador inicial. Pendiente: Administración confirma quién factura en cada sede y si el contado se factura solo con el pago recibido."}]}', 'Procesos');

INSERT INTO supricom_panel.manuales (codigo, titulo, area, version, roles, publicado, contenido, updated_by)
VALUES ('MP-VEN-04', 'Almacén: armado y despacho del pedido', 'Proceso de ventas', '0.1', '[]', 0, '{"objetivo":"Que todo pedido facturado se arme completo, se cuente, se serialice y se despache por el panel, de modo que el inventario de Odoo coincida con lo que sale.","alcance":"Empieza cuando el pedido aparece en la lista de pendientes del panel (facturado, con método de retiro y reservado) y termina cuando el egreso queda en Por verificar para Seguridad.\\n\\nRegla de este manual: R9 de MP-VEN-00. La orden de entrega se valida solo por el panel, nunca a mano en Odoo.","responsables":[{"rol":"Almacén","responsabilidad":"Registra el egreso, arma, cuenta, empaqueta, carga seriales y asigna el despacho. Avisa al vendedor de cualquier faltante."},{"rol":"Almacenista que arma","responsabilidad":"Arma el pedido y lo cuenta renglón por renglón."},{"rol":"Almacenista que despacha","responsabilidad":"Entrega la mercancía al chofer, al transporte o al cliente."}],"definiciones":[{"termino":"Orden de entrega","definicion":"Documento de inventario de Odoo (CENT1/OUT/…, PRIN1/OUT/…) que nace del pedido. Tiene que estar en estado Listo (reservado) para que Almacén lo vea en el panel."},{"termino":"Método de retiro","definicion":"Cómo recibe el cliente la mercancía: sucursal, ruta, encomienda o transporte. Se registra en el panel (Método de retiro) por cada pedido."},{"termino":"Egreso","definicion":"Registro del panel que sigue la salida de un pedido por etapas: por armar → armando → pre-despacho → (por empaquetar) → por asignar despacho → por verificar → por calificar → cerrado."},{"termino":"Despacho parcial","definicion":"Salida de solo parte del pedido. Requiere motivo; lo que no sale queda en Odoo como entrega pendiente."}],"pasos":[{"titulo":"Registrar el egreso","responsable":"Almacén","descripcion":"Sistema: panel › Mercancía › Egreso › Nuevo.\\n- Elige el pedido en la lista de pendientes. Ahí solo aparecen órdenes de entrega Listas, con factura publicada y sin egreso.\\n- Indica quién arma el pedido (del catálogo de almacenistas de la sede).\\n- El panel rechaza el pedido si está cancelado, si no tiene reserva, si no tiene método de retiro o si no tiene factura. Si un pedido que esperas no aparece, avisa al vendedor: le falta algo de MP-VEN-01 o MP-VEN-03.\\n\\nCriterio de salida: egreso en etapa Por armar.","imagenes":[],"nota":"Nunca valides la orden de entrega directamente en Odoo, aunque tengas permiso: la salida se hace siempre por el panel."},{"titulo":"Armar y verificar el armado","responsable":"Almacén","descripcion":"Sistema: panel › detalle del egreso.\\n- Pulsa Iniciar armado y, al terminar, Terminar armado.\\n- Cuenta cada renglón y anota la cantidad. El panel solo deja avanzar si todo coincide con el pedido.\\n- Si falta mercancía, confirma un despacho parcial con el motivo y avisa al vendedor el mismo día.\\n\\nCriterio de salida: armado verificado. Si es encomienda pasa a Por empaquetar; si no, a Por asignar despacho.","imagenes":[],"nota":""},{"titulo":"Empaquetar (solo encomienda)","responsable":"Almacén","descripcion":"Sistema: panel › detalle del egreso › Empaquetado.\\n- Embala la mercancía, identifica los bultos con el cliente y el número de pedido, y marca el empaquetado.\\n\\nCriterio de salida: egreso en Por asignar despacho.","imagenes":[],"nota":""},{"titulo":"Asignar el despacho y validar en Odoo","responsable":"Almacén","descripcion":"Sistema: panel › detalle del egreso › Asignar despacho.\\n- Indica el almacenista que despacha.\\n- Si es ruta: elige chofer y placa del catálogo. El panel rechaza una unidad que esté en el taller.\\n- Carga los seriales de los productos que los llevan (botón Serializar). Sin seriales completos no se puede asignar.\\n- Al asignar, el panel valida la orden de entrega en Odoo y descuenta el inventario. Si es parcial, lo que falta queda como entrega pendiente.\\n- Imprime el recibo de entrega para el cliente.\\n\\nCriterio de salida: egreso en Por verificar y orden de entrega validada en Odoo.","imagenes":[],"nota":""},{"titulo":"Corregir después de una novedad","responsable":"Almacén","descripcion":"- Si Seguridad devuelve el egreso, revisa la novedad, corrige y vuelve a asignar el despacho.\\n- Si la mercancía salió con novedades o se canceló un pedido ya validado, haz la devolución o el ajuste en Odoo el mismo día y avisa al Gerente de Ventas. El panel no lo corrige solo.","imagenes":[],"nota":""}],"documentos":"REGISTROS\\n- Egreso, conteo, seriales, chofer y placa: panel.\\n- Orden de entrega validada y entregas pendientes: Odoo.\\n\\nINDICADORES\\n- Órdenes de entrega validadas a mano en Odoo, fuera del panel. Meta: 0.\\n- Pedidos con mercancía entregada cuyo pedido quedó cancelado. Meta: 0. Hoy: 14 (abr-oct 2026).\\n- Egresos devueltos por Seguridad por errores de armado. Meta: bajar cada mes.","cambios":[{"version":"0.1","fecha":"2026-10-08","descripcion":"Borrador inicial."}]}', 'Procesos');

INSERT INTO supricom_panel.manuales (codigo, titulo, area, version, roles, publicado, contenido, updated_by)
VALUES ('MP-VEN-05', 'Seguridad: verificación de la salida en el portón', 'Proceso de ventas', '0.1', '[]', 0, '{"objetivo":"Que solo salga por el portón la mercancía que corresponde al pedido facturado, verificada serial por serial y con el acta firmada.","alcance":"Empieza cuando el egreso llega a Por verificar y termina cuando queda Cerrado con su calificación.\\n\\nRegla de este manual: R9 de MP-VEN-00.","responsables":[{"rol":"Seguridad","responsabilidad":"Verifica con el escáner, decide qué hacer con las novedades, firma el acta con su clave personal y califica el armado y el despacho."},{"rol":"Almacén","responsabilidad":"Corrige lo que Seguridad le devuelve (MP-VEN-04)."}],"definiciones":[{"termino":"Egreso","definicion":"Registro del panel que sigue la salida de un pedido por etapas: por armar → armando → pre-despacho → (por empaquetar) → por asignar despacho → por verificar → por calificar → cerrado."},{"termino":"Novedad","definicion":"Diferencia que Seguridad encuentra en el portón: serial que no corresponde, cantidad distinta, producto ajeno o algo que no salió."},{"termino":"Despacho parcial","definicion":"Salida de solo parte del pedido. Requiere motivo; lo que no sale queda en Odoo como entrega pendiente."}],"pasos":[{"titulo":"Verificar la salida en el portón","responsable":"Seguridad","descripcion":"Sistema: panel › Mercancía › verificación en portón.\\n- Escanea cada serial y cuenta cada renglón contra la orden de entrega.\\n- Sin novedades: aprueba la salida.\\n- Con novedades: anota el motivo y decide despachar, devolver al almacén, cancelar o despachar parcial.\\n- Firma el acta con tu clave personal. Pide la firma del cliente o del chofer cuando sea posible.\\n- El panel vuelve a consultar Odoo: si el pedido se canceló o perdió la factura, la mercancía no sale.\\n\\nCriterio de salida: salida aprobada y acta firmada.","imagenes":[],"nota":"Si decides despachar con novedades o cancelar un pedido ya validado, avisa el mismo día a Almacén y al Gerente de Ventas: la corrección en Odoo no es automática."},{"titulo":"Calificar y cerrar el egreso","responsable":"Seguridad","descripcion":"Sistema: panel › detalle del egreso › Calificar.\\n- Califica de 1 a 5 el armado y el despacho.\\n- Si hubo novedades y das 4 o 5 al armado, explica por qué en el comentario.\\n\\nCriterio de salida: egreso Cerrado. Aquí termina el proceso de venta.","imagenes":[],"nota":""}],"documentos":"REGISTROS\\n- Escaneos, novedades, decisión, acta firmada y calificaciones: panel, egreso.\\n\\nINDICADORES\\n- Egresos que salieron con novedades sin avisar a Almacén y Ventas. Meta: 0.\\n- Egresos sin la firma del cliente o del chofer. Meta: bajar cada mes.","cambios":[{"version":"0.1","fecha":"2026-10-08","descripcion":"Borrador inicial."}]}', 'Procesos');

-- Después: deben aparecer 6 filas.
SELECT id, codigo, titulo, area, version, publicado FROM supricom_panel.manuales WHERE codigo IN ('MP-VEN-00', 'MP-VEN-01', 'MP-VEN-02', 'MP-VEN-03', 'MP-VEN-04', 'MP-VEN-05') ORDER BY codigo;
